package vikoba.service.dividend.entity;
import jakarta.persistence.*; import lombok.*; import vikoba.service.common.entity.BaseEntity; import vikoba.service.organization.entity.*; import java.math.BigDecimal;
@Entity @Table(name="dividends", uniqueConstraints=@UniqueConstraint(name="uk_dividend_group_member_year", columnNames={"group_id","group_member_id","financial_year"}))
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Dividend extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY,optional=false) private VikobaGroup group; @ManyToOne(fetch=FetchType.LAZY,optional=false) private GroupMember groupMember; @Column(name="financial_year",nullable=false) private Integer financialYear; @Column(nullable=false,precision=19,scale=2) private BigDecimal profitPool; @Column(nullable=false,precision=19,scale=2) @Builder.Default private BigDecimal contributions=BigDecimal.ZERO; @Column(nullable=false,precision=19,scale=2) @Builder.Default private BigDecimal finesAssessed=BigDecimal.ZERO; @Column(nullable=false,precision=19,scale=2) @Builder.Default private BigDecimal finesPaid=BigDecimal.ZERO; @Column(nullable=false,precision=19,scale=2) @Builder.Default private BigDecimal fineDeduction=BigDecimal.ZERO; @Column(nullable=false) private Integer sharesOwned; @Column(nullable=false,precision=19,scale=2) private BigDecimal shareValue; @Column(nullable=false,precision=19,scale=2) private BigDecimal amount; @Column(nullable=false,length=20) @Builder.Default private String status="GENERATED"; }
